import java.util.*;

class Solution {
    public int wireCost(int[][] points) {
        int n = points.length, total = 0;
        int[] best = new int[n]; // cheapest wire from each post to the tree
        boolean[] inTree = new boolean[n];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[0] = 0;
        for (int round = 0; round < n; round++) {
            int u = -1;
            for (int i = 0; i < n; i++)
                if (!inTree[i] && (u == -1 || best[i] < best[u])) u = i; // closest outside post
            inTree[u] = true;
            total += best[u];
            for (int j = 0; j < n; j++) {
                if (inTree[j]) continue;
                int d = Math.abs(points[u][0] - points[j][0]) + Math.abs(points[u][1] - points[j][1]);
                if (d < best[j]) best[j] = d;
            }
        }
        return total;
    }
}

