class Solution:
    def wireCost(self, points: List[List[int]]) -> int:
        n = len(points); best = [inf] * n; used = [False] * n; best[0] = 0; total = 0
        for _ in range(n):
            v = min((i for i in range(n) if not used[i]), key=lambda i: best[i])
            used[v] = True; total += best[v]
            for u in range(n):
                if not used[u]:
                    d = abs(points[v][0] - points[u][0]) + abs(points[v][1] - points[u][1])
                    if d < best[u]: best[u] = d
        return total

