function wireCost(points) {
  const n = points.length, e = [];
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) e.push([Math.abs(points[i][0]-points[j][0]) + Math.abs(points[i][1]-points[j][1]), i, j]);
  e.sort((a, b) => a[0] - b[0]);
  const p = [...Array(n).keys()], f = x => { while (p[x] !== x) { p[x] = p[p[x]]; x = p[x]; } return x; };
  let total = 0;
  for (const [w, a, b] of e) { const ra = f(a), rb = f(b); if (ra !== rb) { p[ra] = rb; total += w; } }
  return total;
}
